def generate_high_color_pattern(N):
    # This pattern is designed to maximize local diversity while maintaining the 2x2 constraint.
    # It uses 4 colors (1, 2, 3, 4).
    colors = []
    for i in range(N):
        row = []
        for j in range(N):
            if (i % 2 == 0 and j % 2 == 0):
                color = 1
            elif (i % 2 == 0 and j % 2 == 1):
                color = 2
            elif (i % 2 == 1 and j % 2 == 0):
                color = 4
            else: # i%2 == 1 and j%2 == 1
                color = 3
            row.append(color)
        colors.append(row)
    return colors

grid = generate_high_color_pattern(10)

print("Generated 10x10 grid (4 colors):")
for row in grid:
    print(row)

# Verification function
def check_constraint(grid):
    N = len(grid)
    for i in range(N - 1):
        for j in range(N - 1):
            block = [
                grid[i][j], grid[i][j+1],
                grid[i+1][j], grid[i+1][j+1]
            ]
            # Check if all four are distinct
            if len(set(block)) == 4:
                print(f"Constraint failed at ({i}, {j})! Colors: {block}")
                return False
    return True

print("\nConstraint Check:")
if check_constraint(grid):
    print("The generated 10x10 grid satisfies the constraint.")
else:
    print("The generated 10x10 grid violates the constraint.")
